/* Presentation recipes use the same patient renderer and guarded clinic updates. */
(function (root) {
  const M = root.CareFlowModel;
  const patient = (title, screen, done) => ({title, screen, done: typeof done === 'string' ? c => c.u.screen === done : done});
  const clinic = (title, screen, event, done) => ({title, screen, event, done, owner:'Phòng khám'});
  const status = value => c => c.v?.status === value;
  const event = (title, screen, name, value) => clinic(title,screen,name,status(value));
  const booking = () => [patient('Chọn người đi khám','C1','C2'),patient('Lý do khám và tiền sử','C2','C3'),patient('Sàng lọc trước khi đặt lịch','C3','C6'),patient('Chọn hình thức khám','C6','C7'),...send()];
  const send = () => [patient('Chọn ngày, giờ mong muốn','C7','C8'),patient('Kiểm tra và gửi yêu cầu','C8','C9'),patient('Mở phiếu khám','C9','D2')];
  const confirm = () => [event('Lễ tân xác nhận lịch','D2','visit:confirmed','confirmed'),clinic('Thông báo phí khám','D2','fee:package',c=>c.v?.feePlan==='package')];
  const login = () => [patient('Nhận mã xác nhận','A1',c=>c.u.otpSent),patient('Xác nhận số điện thoại','A1',c=>c.s.authenticated)];
  const care = screen => [clinic('Điều phối viên tiếp nhận',screen,'handoff:coordinating',c=>c.v?.care.tasks?.at(-1)?.status==='coordinating'),clinic('Chuyển thông tin cho bác sĩ',screen,'handoff:doctor-review',c=>c.v?.care.tasks?.at(-1)?.status==='doctor-review'),clinic('Bác sĩ xem và phản hồi','I5','handoff:answered',c=>c.v?.care.tasks?.at(-1)?.status==='answered')];
  const online = () => [patient('Chuẩn bị thiết bị','G1',c=>c.u.deviceReady),event('Phòng khám mở phòng chờ','G1','visit:reminder','reminder'),patient('Vào phòng chờ','G1',status('online-wait')),event('Bác sĩ gọi cho bạn','G2','visit:calling','calling')];
  const consult = () => [patient('Nhận cuộc gọi','G3',status('in-consult')),event('Bác sĩ hoàn tất, ký hồ sơ','G4','visit:completed','completed'),clinic('Chia sẻ thông tin sau khám','H6','summary',c=>!!c.v?.summary)];
  const labReady = () => [clinic('Điều dưỡng nhận kết quả','H7','lab-status:lab-1:available',c=>c.l?.status==='available'),clinic('Chuyển bác sĩ xem','H7','lab-status:lab-1:awaiting-review',c=>c.l?.status==='awaiting-review'),clinic('Bác sĩ đã xem kết quả','H7','lab-status:lab-1:reviewed',c=>c.l?.status==='reviewed')];
  const flows = [
    {id:'F1',title:'Lần đầu đặt lịch',description:'Tạo hồ sơ, sàng lọc và nhận xác nhận lịch.',scenario:'new',steps:()=>[...login(),patient('Tạo hồ sơ bệnh nhân','A3','B1'),patient('Bắt đầu đặt lịch','B1','C1'),...booking(),...confirm()]},
    {id:'F2',title:'Đã có hồ sơ',description:'Xác nhận thông tin cũ và tiếp tục đặt lịch.',scenario:'returning',steps:()=>[...login(),patient('Xác nhận, cập nhật hồ sơ cũ','A2','B1'),patient('Đặt lịch với hồ sơ đã có','B1','C1'),...booking(),...confirm()]},
    {id:'F3',title:'Cần hỗ trợ khẩn cấp',description:'Ưu tiên trợ giúp, phòng khám xem xét hình thức khám.',scenario:'empty',variants:[['review','Vẫn muốn khám'],['emergency','Tìm trợ giúp khẩn cấp']],steps:variant=>variant==='emergency'?[patient('Xem các kênh trợ giúp','C4',c=>c.u.emergencyOpened),patient('Mở liên hệ hoặc chỉ đường cơ sở','C4',c=>c.u.emergencyAccessed)]:[patient('Đọc khuyến cáo và yêu cầu xem xét','C4','C5'),patient('Chờ phòng khám chốt hình thức','C5','C7'),...send(),clinic('Bác sĩ xem xét hình thức phù hợp','D2','review:onsite',status('pending')),...confirm()]},
    {id:'F4',title:'Đến phòng khám',description:'Báo đã đến, tiếp nhận và theo dõi buổi khám.',scenario:'upcoming',steps:()=>[patient('Xem hướng dẫn, báo đã đến','E2',status('arrived')),event('Lễ tân tiếp nhận','E3','visit:received','received'),event('Chuẩn bị vào khám','E3','visit:ready','ready'),event('Bác sĩ bắt đầu khám','E3','visit:in-consult','in-consult'),event('Ký và hoàn tất lượt khám','E3','visit:completed','completed'),clinic('Nhận thông tin sau khám','H6','summary',c=>!!c.v?.summary)]},
    {id:'F5',title:'Xét nghiệm trước khám',description:'Đặt hẹn, gửi kết quả và tiếp tục lượt khám hiện tại.',scenario:'pre-lab',variants:[['visit','Quay lại lượt khám'],['during','Xem trong buổi khám']],steps:()=>[patient('Xem chỉ định xét nghiệm','F2','F3'),patient('Gửi thời gian mong muốn','F3',c=>c.l?.status==='scheduled'),patient('Đính kèm kết quả','F4',c=>c.l?.status==='available'),event('Điều dưỡng xác nhận cách tiếp tục','F2','visit:confirmed','confirmed'),patient('Tiếp tục theo hướng dẫn phòng khám','F2',c=>['D2','E3'].includes(c.u.screen))]},
    {id:'F6',title:'Hủy, đổi hoặc đặt lại lịch',description:'Giữ lý do và lịch sử, liên kết lượt khám mới.',scenario:'upcoming',variants:[['cancel','Hủy lịch'],['no-show','Không đến'],['reschedule','Đổi lịch']],steps:variant=>[...(variant==='cancel'?[patient('Hủy lịch và ghi lý do','D4',status('cancelled')),patient('Chọn đặt lại lịch','D2','C7')]:variant==='no-show'?[patient('Xem ghi nhận và đặt lại lịch','D2','C7')]:[patient('Chọn đổi lịch','D3','C7')]),...send(),...confirm()]},
    {id:'F7',title:'Khám online',description:'Chuẩn bị, nhận cuộc gọi và xem thông tin sau khám.',scenario:'online',steps:()=>[...online(),...consult()]},
    {id:'F8',title:'Kết nối lại với phòng khám',description:'Gọi lại, hẹn online khác hoặc chuyển đến phòng khám.',scenario:'online',variants:[['callback','Chờ gọi lại'],['online','Hẹn online khác'],['onsite','Đến phòng khám']],steps:variant=>variant==='callback'?[event('Phòng khám sắp xếp gọi lại','G5','visit:online-wait','online-wait'),event('Cuộc gọi mới từ bác sĩ','G2','visit:calling','calling'),...consult()]:[patient('Chọn lịch và hình thức mới','G5','C7'),...send(),...confirm()]},
    {id:'F9',title:'Thanh toán phí khám',description:'Chọn cách thanh toán, theo dõi biên lai và hoàn tiền.',scenario:'completed',variants:[['transfer','Chuyển khoản'],['counter','Tại quầy'],['pharmacy','Nhà thuốc'],['later','Thanh toán sau'],['refund','Hoàn tiền'],['free','Không thu phí']],steps:variant=>variant==='free'?[clinic('Phòng khám xác nhận không thu phí','H2','payment:not-required',c=>c.v?.payment.status==='not-required')]:[...(variant==='later'?[patient('Gửi lý do và ngày thanh toán','H3',c=>c.v?.payment.status==='deferred'),patient('Chọn cách thanh toán khi đến hẹn','H2',c=>c.v?.payment.status==='counter-pending')]:[patient(variant==='transfer'?'Thông báo đã chuyển khoản':'Chọn nơi thanh toán',variant==='transfer'?'H4':'H2',c=>['transfer-pending','counter-pending','pharmacy-pending'].includes(c.v?.payment.status))]),clinic('Phòng khám xác nhận khoản thu','H5','payment:paid',c=>c.v?.payment.status==='paid'),...(variant==='refund'?[clinic('Tiếp nhận và kiểm tra hoàn tiền','H5','payment:refunding',c=>c.v?.payment.status==='refunding'),clinic('Cập nhật khoản hoàn','H5','payment:refunded',c=>c.v?.payment.status==='refunded')]:[])]},
    {id:'F10',title:'Kết quả sau khám',description:'Bác sĩ xem, thông báo và hướng dẫn việc tiếp theo.',scenario:'completed',variants:[['summary','Thông tin điều trị'],['more','Xét nghiệm tiếp theo'],['explain','Hẹn giải thích kết quả'],['callback','Chưa liên hệ được']],steps:variant=>[...labReady(),...(variant==='callback'?[clinic('Ghi nhận chưa liên hệ được','H7','communicate:unreachable',c=>c.v?.communication.result==='unreachable')]:[]),clinic('Thông báo kết quả cho bạn','H7','communicate:notified',c=>c.v?.communication.result==='notified'),...(variant==='more'?[clinic('Bác sĩ thêm chỉ định','F1','lab:post',c=>c.v?.labs.length>1)]:variant==='explain'?[patient('Hẹn giải thích, không thu phí','H7','C7'),...send()]:[clinic('Chia sẻ thông tin buổi khám','H6','summary',c=>!!c.v?.summary),clinic('Ghi nhận đã trao đổi kết quả','H7','communicate:explained',c=>c.v?.communication.explanation==='explained')])]},
    {id:'F11',title:'Trao đổi và theo dõi sau khám',description:'Phản hồi, chuyển chuyên khoa và bàn giao cho bác sĩ.',scenario:'completed',variants:[['medicine','Đơn thuốc'],['question','Hỏi lại'],['symptoms','Triệu chứng mới'],['urgent','Cần trợ giúp khẩn cấp'],['tracking','Theo dõi'],['referral','Chuyên khoa']],steps:variant=>variant==='urgent'?[patient('Gửi tình trạng cần được trợ giúp','I2','C4'),patient('Xem hướng dẫn và liên hệ phòng khám','C4','I5'),...care('I5')]:[...(variant==='referral'?[clinic('Bác sĩ giới thiệu chuyên khoa','I4','referral',c=>!!c.v?.care.referral)]:[]),patient('Gửi cập nhật cho phòng khám',variant==='tracking'?'I3':variant==='referral'?'I4':'I2',c=>!!c.v?.care.tasks?.length),...care(variant==='tracking'?'I3':'I5')]},
    {id:'F12',title:'Tái khám',description:'Giữ hồ sơ cũ, cập nhật tình trạng và bắt đầu lượt mới.',scenario:'completed',steps:()=>[patient('Đặt lịch từ lượt khám trước','J1','C2'),patient('Cập nhật lý do và tiền sử','C2','C3'),patient('Sàng lọc lại tình trạng hiện tại','C3','C6'),patient('Chọn hình thức tái khám','C6','C7'),...send(),...confirm(),event('Nhắc lịch trước buổi tái khám','D2','visit:reminder','reminder')]},
  ];
  function seed(flow,variant) {
    const s=flow.scenario==='new'?M.initial():M.fixture(flow.scenario);
    let v=M.visit(s);
    if(flow.scenario==='returning')s.authenticated=false;
    if(flow.id==='F3'){
      M.beginBooking(s);Object.assign(s.draft,{reason:'Tôi cần phòng khám xem xét tình trạng hiện tại.',slot:'09:00'});M.screenSafety(s,'warning');
    }
    if(flow.id==='F4')M.transition(s,v.id,'reminder','staff');
    if(flow.id==='F5')v.labs[0].returnPath=variant==='during'?'during':'visit';
    if(flow.id==='F6'&&variant==='no-show'){M.transition(s,v.id,'reminder','staff');M.transition(s,v.id,'no-show','staff');}
    if(flow.id==='F8')for(const to of ['reminder','online-wait','unreachable'])M.transition(s,v.id,to,'staff');
    return s;
  }
  root.CareFlowJourney={flows,seed};
})(window);
